def main():
 data=list(map(int,sys.stdin.buffer.read().split()))
 if not data:return
 n=data[0]; A=data[1:]
 primes=set()
 for x in A:
  y=x; q=2
  while q*q<=y:
   if y%q==0:
    primes.add(q)
    while y%q==0:y//=q
   q+=1
  if y>1:primes.add(y)
 ans=1
 for p in primes:
  ex=[]
  total=0
  for x in A:
   a=0
   while x%p==0:
    a+=1; x//=p
   ex.append(a); total+=a
  pw=[1]
  for _ in range(total): pw.append(pw[-1]*p%MOD)
  dp=[1]
  for idx,a in enumerate(ex):
   if a==0:
    dp=[v*pw[h]%MOD for h,v in enumerate(dp)]
