    raw=h-a
    if raw>=0:
     nd[raw]=(nd[raw]+v*pw[raw])%MOD
    else:
     nd[0]=(nd[0]+v*pow(p,(-raw)*shiftcnt,MOD))%MOD
   dp=nd
