import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n = next(it)
    q = next(it)

    parent = list(range(n))
    left = list(range(n))
    right = list(range(n))
    color = [i + 1 for i in range(n)]
    count = [0] + [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def merge(a, b):
        a = find(a)
        b = find(b)
        if a == b:
            return a
        parent[b] = a
        if left[b] < left[a]:
            left[a] = left[b]
        if right[b] > right[a]:
            right[a] = right[b]
        return a

    ans = []
    for _ in range(q):
        typ = next(it)
        if typ == 1:
            x = next(it) - 1
            c = next(it)
            root = find(x)
            old = color[root]
            size = right[root] - left[root] + 1
            if old != c:
                count[old] -= size
                count[c] += size
                color[root] = c

            if left[root] > 0:
                neighbor = find(left[root] - 1)
                if color[neighbor] == c:
                    root = merge(root, neighbor)
            if right[root] + 1 < n:
                neighbor = find(right[root] + 1)
                if color[neighbor] == c:
                    root = merge(root, neighbor)
        else:
            ans.append(str(count[next(it)]))

    sys.stdout.write("\n".join(ans))

if __name__ == "__main__":
    main()

