from typing import List
class Solution:
    def maxSubarrays(self,n:int,conflictingPairs:List[List[int]])->int:
        by=[[] for _ in range(n+1)]
        for i,(x,y) in enumerate(conflictingPairs):
            a,b=(x,y) if x<y else (y,x)
            by[b].append((a,i))
        mx1=(0,-1); mx2=(0,-1)
        gain=[0]*len(conflictingPairs)
        base=0
        for r in range(1,n+1):
            for a,i in by[r]:
                if a>mx1[0]:
                    mx2=mx1; mx1=(a,i)
                elif a>mx2[0]:
                    mx2=(a,i)
            base += r-mx1[0]
            if mx1[1]>=0: gain[mx1[1]] += mx1[0]-mx2[0]
        return base+max(gain)

