from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        starts_at = [[] for _ in range(n + 1)]
        for idx, (x, y) in enumerate(conflictingPairs):
            a, b = (x, y) if x < y else (y, x)
            starts_at[b].append((a, idx))

        # The two largest left endpoints among pairs whose right endpoint
        # has been reached.  Pair indices are retained so gains can be assigned.
        first = (0, -1)
        second = (0, -1)
        gains = [0] * len(conflictingPairs)
        baseline = 0

        for right in range(1, n + 1):
            for left, idx in starts_at[right]:
                if left > first[0]:
                    second = first
                    first = (left, idx)
                elif left > second[0]:
                    second = (left, idx)

            baseline += right - first[0]
            if first[1] != -1:
                gains[first[1]] += first[0] - second[0]

        return baseline + max(gains)

