import sys

def main():
    a = list(map(int, sys.stdin.buffer.read().split()))
    if not a:
        return
    p = 0
    n, m, q = a[p], a[p+1], a[p+2]
    p += 3
    edges = []
    for _ in range(m):
        edges.append((a[p]-1, a[p+1]-1, a[p+2]))
        p += 3
    queries = []
    closed = [False] * m
    for _ in range(q):
        t = a[p]; p += 1
        if t == 1:
            e = a[p] - 1; p += 1
            queries.append((1, e))
            closed[e] = True
        else:
            x, y = a[p]-1, a[p+1]-1
            p += 2
            queries.append((2, x, y))

    INF = 10**30
    d = [[INF] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for k, (u, v, w) in enumerate(edges):
        if not closed[k]:
            d[u][v] = w
            d[v][u] = w

    # Floyd-Warshall, maintaining only the upper triangle explicitly.
    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            x = di[k]
            if x == INF:
                continue
            for j in range(i, n):
                z = x + dk[j]
                if z < di[j]:
                    di[j] = z
                    d[j][i] = z

    out = []
    for qu in reversed(queries):
        if qu[0] == 2:
            v = d[qu[1]][qu[2]]
            out.append(str(-1 if v == INF else v))
        else:
            u, v, w = edges[qu[1]]
            du = [d[i][u] for i in range(n)]
            dv = [d[i][v] for i in range(n)]
            for i in range(n):
                di = d[i]
                x = du[i]
                y = dv[i]
                for j in range(i, n):
                    z = x + w + dv[j]
                    zz = y + w + du[j]
                    if zz < z:
                        z = zz
                    if z < di[j]:
                        di[j] = z
                        d[j][i] = z
    sys.stdout.write('\n'.join(reversed(out)))

