import sys, heapq

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    rows = [x.decode() for x in data[1:]]
    inf = 10**9
    pre = [[[] for _ in range(26)] for _ in range(n)]
    out = [[[] for _ in range(26)] for _ in range(n)]
    dist = [[inf] * n for _ in range(n)]
    heap = []
    for i in range(n):
        dist[i][i] = 0
        heapq.heappush(heap, (0, i, i))
        for j, ch in enumerate(rows[i]):
            if ch != '-':
                k = ord(ch) - 97
                out[i][k].append(j)
                pre[j][k].append(i)
                if dist[i][j] > 1:
                    dist[i][j] = 1
                    heapq.heappush(heap, (1, i, j))

    row_max = [max(row) for row in dist]
    while heap:
        cur, u, v = heapq.heappop(heap)
        if cur != dist[u][v]:
            continue
        nxt = cur + 2
        for k in range(26):
            right = out[v][k]
            for a in pre[u][k]:
                row = dist[a]
                # No entry in this row can be improved if even its
                # largest current distance is no greater than nxt.
                if row_max[a] <= nxt:
                    continue
                for b in right:
                    old = row[b]
                    if nxt < old:
                        row[b] = nxt
                        heapq.heappush(heap, (nxt, a, b))
                        if old == row_max[a]:
                            row_max[a] = max(row)

    for row in dist:
        print(*(-1 if x == inf else x for x in row))

if __name__ == '__main__':
    solve()

