import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    u = vals[::2]
    d = vals[1::2]

    upper = min(a + b for a, b in zip(u, d))

    def feasible(h):
        # [low, high] is the set of possible upper-tooth lengths
        # at the current position.
        low = max(0, h - d[0])
        high = min(u[0], h)
        if low > high:
            return False
        for i in range(1, n):
            low = max(max(0, h - d[i]), low - x)
            high = min(min(u[i], h), high + x)
            if low > high:
                return False
        return True

    lo, hi = 0, upper
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    print(sum(u) + sum(d) - n * lo)

if __name__ == '__main__':
    main()

