import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    pos = 2
    for _ in range(m):
        u = data[pos] - 1
        v = data[pos + 1] - 1
        pos += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Put the adjacency matrix into reduced row echelon form over F_2.
    pivots = []
    r = 0
    for c in range(n):
        q = None
        for i in range(r, n):
            if (rows[i] >> c) & 1:
                q = i
                break
        if q is None:
            continue
        rows[r], rows[q] = rows[q], rows[r]
        for i in range(n):
            if i != r and ((rows[i] >> c) & 1):
                rows[i] ^= rows[r]
        pivots.append((c, rows[r]))
        r += 1

    pivot_columns = {c for c, _ in pivots}
    null_basis = []
    for free in range(n):
        if free in pivot_columns:
            continue
        vec = 1 << free
        for pivot, equation in pivots:
            if (equation >> free) & 1:
                vec |= 1 << pivot
        null_basis.append(vec)

    answer = []
    for vertex in range(n):
        value = 0
        for bit, vec in enumerate(null_basis):
            if (vec >> vertex) & 1:
                value |= 1 << bit
        answer.append(value)

    if any(value == 0 for value in answer):
        print("No")
    else:
        print("Yes")
        print(*answer)

