N = int(sys.stdin.buffer.read())

# If d = x-y, then N = d(3y^2 + 3dy + d^2),
# and positive y implies d^3 < N.  Find the largest such d.
lo, hi = 0, 1
while hi * hi * hi < N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid * mid * mid < N:
        lo = mid
    else:
        hi = mid

for d in range(1, lo + 1):
    if N % d != 0:
        continue
    q = N // d
    # (6y+3d)^2 = 12q - 3d^2
    value = 12 * q - 3 * d * d
    if value <= 0:
        continue
    z = math.isqrt(value)
    if z * z != value or z <= 3 * d or (z - 3 * d) % 6 != 0:
        continue
    y = (z - 3 * d) // 6
    print(y + d, y)
    break
else:
    print(-1)

