from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        cap = k
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(cap, fact[i - 1] * i)

        def ways(odd_count: int, even_count: int, first_parity: int) -> int:
            if first_parity == 1:
                if odd_count != even_count and odd_count != even_count + 1:
                    return 0
            else:
                if even_count != odd_count and even_count != odd_count + 1:
                    return 0
            return min(cap, fact[odd_count] * fact[even_count])

        odd_count = (n + 1) // 2
        even_count = n // 2
        total = min(cap, ways(odd_count, even_count, 1) +
                    ways(odd_count, even_count, 0))
        if k > total:
            return []

        remaining = list(range(1, n + 1))
        answer = []
        previous_parity = -1

        for _ in range(n):
            selected = -1
            for i, value in enumerate(remaining):
                parity = value & 1
                if previous_parity != -1 and parity == previous_parity:
                    continue

                remaining_odd = sum(v & 1 for v in remaining) - (parity == 1)
                remaining_even = len(remaining) - 1 - remaining_odd
                block = ways(remaining_odd, remaining_even, 1 - parity)

                if k > block:
                    k -= block
                else:
                    selected = i
                    break

            if selected == -1:
                return []
            value = remaining.pop(selected)
            answer.append(value)
            previous_parity = value & 1

        return answer

