class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # p[i] is 10**i modulo k.  Each digit in the first half
        # contributes to one or two positions of the palindrome.
        p = [1] * n
        for i in range(1, n):
            p[i] = (p[i - 1] * 10) % k

        weight = [0] * half
        for i in range(half):
            j = n - 1 - i
            if i == j:
                weight[i] = p[i]
            else:
                weight[i] = (p[i] + p[j]) % k

        # possible[i][r] says that positions i and onward can contribute
        # residue r.  There are only k residues (k <= 9).
        possible = [bytearray(k) for _ in range(half + 1)]
        possible[half][0] = 1
        for i in range(half - 1, -1, -1):
            row = possible[i]
            nxt = possible[i + 1]
            wi = weight[i]
            for digit in range(10):
                add = digit * wi % k
                for residue in range(k):
                    if nxt[residue]:
                        row[(add + residue) % k] = 1

        # Greedily choose the largest digit whose suffix can complete
        # the number to residue zero.
        residue = 0
        left = []
        for i in range(half):
            low = 1 if i == 0 else 0
            for digit in range(9, low - 1, -1):
                new_residue = (residue + digit * weight[i]) % k
                if possible[i + 1][(-new_residue) % k]:
                    left.append(str(digit))
                    residue = new_residue
                    break

        prefix = ''.join(left)
        if n % 2:
            return prefix + prefix[-2::-1]
