from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # nxt[i] is the first position to the right whose value is larger.
        nxt = [-1] * n
        stack = []
        for i, x in enumerate(nums):
            while stack and nums[stack[-1]] < x:
                nxt[stack.pop()] = i
            stack.append(i)

        # A jump from i to nxt[i] skips a block having target value nums[i].
        levels = n.bit_length()
        up = [nxt]
        block_sum = [[nums[i] * (nxt[i] - i) if nxt[i] != -1 else 0
                      for i in range(n)]]
        for _ in range(1, levels):
            prev_u, prev_s = up[-1], block_sum[-1]
            cur_u = [-1] * n
            cur_s = [0] * n
            for i in range(n):
                m = prev_u[i]
                if m != -1 and prev_u[m] != -1:
                    cur_u[i] = prev_u[m]
                    cur_s[i] = prev_s[i] + prev_s[m]
            up.append(cur_u)
            block_sum.append(cur_s)

        prefix = [0] * (n + 1)
        for i, x in enumerate(nums):
            prefix[i + 1] = prefix[i] + x

        def required(l: int, r: int) -> int:
            # Sum of the prefix maxima on nums[l:r+1], minus the original sum.
            p = l
            target_sum = 0
            for z in range(levels - 1, -1, -1):
                q = up[z][p]
                if q != -1 and q <= r:
                    target_sum += block_sum[z][p]
                    p = q
            target_sum += nums[p] * (r - p + 1)
            return target_sum - (prefix[r + 1] - prefix[l])

        ans = 0
        right = -1
        for left in range(n):
            if right < left:
                right = left
            while right + 1 < n and required(left, right + 1) <= k:
                right += 1
            ans += right - left + 1
        return ans

