import sys
from functools import cmp_to_key

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, k = data[0], data[1]
    funcs = [(data[i], data[i + 1]) for i in range(2, len(data), 2)]

    # Sort by B/(A-1) in descending order.  A=1 represents infinity.
    def compare(x, y):
        a, b = x
        c, d = y
        da, dc = a - 1, c - 1
        if da == 0:
            return 0 if dc == 0 else -1
        if dc == 0:
            return 1
        cross = b * dc - d * da
        return (cross < 0) - (cross > 0)

    funcs.sort(key=cmp_to_key(compare))
    neg_inf = -10**100
    dp = [neg_inf] * (k + 1)
    dp[0] = 1
    for a, b in funcs:
        for used in range(k, 0, -1):
            candidate = a * dp[used - 1] + b
            if candidate > dp[used]:
                dp[used] = candidate
    print(dp[k])

