class Solution:
    def makeStringGood(self, s: str) -> int:
        cnt = [0]*26
        for ch in s:
            cnt[ord(ch)-97] += 1
        n = len(s)
        INF = 10**18
        ans = n
        for k in range(1, n+1):
            dp = {0: 0}
            for a in cnt:
                nd = {}
                for x, v in dp.items():
                    t = x + a
                    # Do not retain this letter.
                    for y, z in ((0, v+t), (t, v+t+t)):
                        if z < nd.get(y, INF): nd[y] = z
                    need = max(0, k-a)
                    used = min(x, need)
                    left = x-used + max(0, a-k)
                    base = v + max(0, k-t)
                    z = base + left
                    if z < nd.get(left, INF): nd[left] = z
                    z = base + 2*left
                    if z < nd.get(0, INF): nd[0] = z
                dp = nd
            ans = min(ans, min(v+x for x,v in dp.items()))
        return ans

