class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        # free[u]: best value in u's subtree when its parent edge is absent
        # used[u]: best value when the edge from u to its parent is present
        free = [0] * n
        used = [0] * n

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += free[v]
                    gains.append(used[v] + w - free[v])
            gains.sort(reverse=True)

            total = 0
            for gain in gains[:k]:
                if gain <= 0:
                    break
                total += gain
            free[u] = base + total

            total = 0
            limit = max(0, k - 1)
            for gain in gains[:limit]:
                if gain <= 0:
                    break
                total += gain
            used[u] = base + total

        return free[0]

