                p = parent[x]
                parent[x] = find(p)
                parity[x] ^= parity[p]
            return parent[x]

        def unite(a, b, v):
            ra = find(a)
            pa = parity[a]
            rb = find(b)
            pb = parity[b]
            if ra == rb:
                return (pa ^ pb) == v
            parent[ra] = rb
            parity[ra] = pa ^ pb ^ v
            return True

        col_prefix = [0] * w
        for i, s in enumerate(rows):
