class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        first, middle, last = p.split('*')
        inf = n + 1

        def occurrences(word):
            if not word:
                return [True] * (n + 1)
            m = len(word)
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and word[i] != word[j]:
                    j = prefix[j - 1]
                if word[i] == word[j]:
                    j += 1
                prefix[i] = j

            result = [False] * (n + 1)
            j = 0
            for i, ch in enumerate(s):
                while j and ch != word[j]:
                    j = prefix[j - 1]
                if ch == word[j]:
                    j += 1
                if j == m:
                    result[i - m + 1] = True
                    j = prefix[j - 1]
            return result

        def next_occurrence(flags):
            result = [inf] * (n + 2)
            nearest = inf
            for i in range(n, -1, -1):
                if flags[i]:
                    nearest = i
                result[i] = nearest
            return result

        has_first = occurrences(first)
        next_middle = next_occurrence(occurrences(middle))
        next_last = next_occurrence(occurrences(last))

        answer = inf
        for start in range(n + 1):
            if not has_first[start]:
                continue
            middle_start = next_middle[start + len(first)]
            if middle_start > n:
                continue
            last_start = next_last[middle_start + len(middle)]
            if last_start <= n:
                answer = min(answer, last_start + len(last) - start)

        return -1 if answer == inf else answer

