    a, b = data[1], data[2]
    n, m = len(a), len(b)
    if abs(n - m) > k:
        print('No')
        return
    mask = (1 << 64) - 1
    base = 911382323
    powers = [1] * (min(n, m) + 1)
    for i in range(1, len(powers)):
        powers[i] = (powers[i - 1] * base) & mask

    def hashes(s):
        h = [0]
        for c in s:
            h.append((h[-1] * base + c + 1) & mask)
        return h

    ha, hb = hashes(a), hashes(b)

    def extend(i, j):
        limit = min(n - i, m - j)
        lo, hi = 0, limit
        while lo < hi:
            q = (lo + hi + 1) // 2
            if ((ha[i + q] - ha[i] * powers[q]) & mask) == ((hb[j + q] - hb[j] * powers[q]) & mask):
                lo = q
            else:
                hi = q - 1
        return i + lo

    x = extend(0, 0)
    if x == n and x == m:
        print('Yes')
        return
    furthest = {0: x}
    for edits in range(1, k + 1):
        nxt = {}
        for diag in range(-edits, edits + 1):
            x = -1
            if diag + 1 in furthest:
