from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Construct the postorder explicitly, without recursion.
        postorder = []
        stack = [(0, 0)]
        while stack:
            v, state = stack.pop()
            if state == 0:
                stack.append((v, 1))
                for u in reversed(children[v]):
                    stack.append((u, 0))
            else:
                postorder.append(v)

        text = [s[v] for v in postorder]

        # Manacher radii for odd-length palindromes.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        # Manacher radii for even-length palindromes.  The center is before i.
        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        position = [0] * n
        for i, v in enumerate(postorder):
            position[v] = i

        subtree_size = [1] * n
        for v in postorder:
            for u in children[v]:
                subtree_size[v] += subtree_size[u]

        answer = [False] * n
        for v in range(n):
            length = subtree_size[v]
            r = position[v]
            l = r - length + 1
            if length & 1:
                center = (l + r) // 2
                answer[v] = odd[center] >= length // 2 + 1
            else:
                center = (l + r + 1) // 2
                answer[v] = even[center] >= length // 2
        return answer

