import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits

        is_prime = [True] * limit
        is_prime[0] = False
        if limit > 1:
            is_prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if is_prime[p]:
                for x in range(p * p, limit, p):
                    is_prime[x] = False

        if is_prime[n] or is_prime[m]:
            return -1

        powers = [10 ** i for i in range(digits)]
        inf = 10 ** 30
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]

        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost

            for power in powers:
                digit = (value // power) % 10
                if digit < 9:
                    nxt = value + power
                    if not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist[nxt]:
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - power
                    if not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist[nxt]:
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))

        return -1

