from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        def z_values(start, length):
            z = [0] * length
            if length == 0:
                return z
            z[0] = length
            left = right = 0
            a = nums
            for k in range(1, length):
                if k < right:
                    v = z[k - left]
                    z[k] = v if v < right-k else right-k
                while k + z[k] < length and a[start + z[k]] == a[start + k + z[k]]:
                    z[k] += 1
                if k + z[k] > right:
                    left, right = k, k + z[k]
            return z

        # z[i] is the LCP of nums and nums[i:].
        whole = z_values(0, n)
        answer = 0
        for i in range(1, n - 1):
            first = whole[i] >= i
            if first:
                answer += max(0, n - 2 * i)

            # The second condition requires the third part to have at
            # least the length of the second part.
            max_b = (n - i) // 2
            if max_b == 0:
                continue
            z = z_values(i, 2 * max_b)
            for b in range(1, max_b + 1):
                if z[b] >= b and not (first and b >= i):
                    answer += 1
        return answer

