class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        weights = sorted({w for _, _, w in edges})
        reverse = [[] for _ in range(n)]
        for a, b, w in edges:
            reverse[b].append((a, w))

        def reachable(limit: int) -> bool:
            seen = [False] * n
            seen[0] = True
            stack = [0]
            count = 1
            while stack:
                v = stack.pop()
                for u, w in reverse[v]:
                    if w <= limit and not seen[u]:
                        seen[u] = True
                        count += 1
                        stack.append(u)
            return count == n

        if not reachable(weights[-1]):
            return -1

        lo, hi = 0, len(weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if reachable(weights[mid]):
                hi = mid
            else:
                lo = mid + 1
        return weights[lo]

