class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**30
        dp = [[INF] * 3 for _ in range(3)]

        # Choose the colors of the two outermost houses.
        for left in range(3):
            for right in range(3):
                if left != right:
                    dp[left][right] = cost[0][left] + cost[n - 1][right]

        # Add pairs of houses, moving from the ends toward the center.
        for i in range(1, n // 2):
            ndp = [[INF] * 3 for _ in range(3)]
            for left in range(3):
                for right in range(3):
                    if left == right:
                        continue
                    best_previous = INF
                    for old_left in range(3):
                        for old_right in range(3):
                            if old_left != left and old_right != right:
                                if dp[old_left][old_right] < best_previous:
                                    best_previous = dp[old_left][old_right]
                    ndp[left][right] = (best_previous + cost[i][left]
                                        + cost[n - 1 - i][right])
            dp = ndp

        return min(min(row) for row in dp)

