class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        point_set = {(x, y) for x, y in points}
        xs = sorted({x for x, y in points})
        ys = sorted({y for x, y in points})
        best = -1

        for xi in range(len(xs)):
            for xj in range(xi + 1, len(xs)):
                x1, x2 = xs[xi], xs[xj]
                for yi in range(len(ys)):
                    for yj in range(yi + 1, len(ys)):
                        y1, y2 = ys[yi], ys[yj]
                        corners = ((x1, y1), (x1, y2),
                                   (x2, y1), (x2, y2))
                        if not all(corner in point_set for corner in corners):
                            continue

                        valid = True
                        for x, y in points:
                            if (x, y) not in corners and x1 <= x <= x2 and y1 <= y <= y2:
                                valid = False
                                break
                        if valid:
                            best = max(best, (x2 - x1) * (y2 - y1))

        return best

