                        if not all(p in s for p in corners):
                            continue
                        if any(x1 <= x <= x2 and y1 <= y <= y2 and (x,y) not in corners for x,y in points):
                            continue
                        ans=max(ans,(x2-x1)*(y2-y1))
        return ans

